mapper.select:
SELECT COUNT(*) FROM POS_INGEST_FILE
 WHERE FILE_NAME = #{fileName} AND SHA256 = #{sha256}
   AND STATUS IN ('DONE', 'PARTIAL', 'STALE')

mapper.update:
MERGE INTO POS_STATION t
USING DUAL ON (t.STATION_CODE = #{row.stationCode})
WHEN MATCHED THEN UPDATE SET t.STATION_NAME = #{row.stationName}, t.NAME_SRC_TIME = #{src}
 WHERE t.NAME_SRC_TIME IS NULL OR t.NAME_SRC_TIME <= #{src}
WHEN NOT MATCHED THEN INSERT (STATION_CODE, STATION_NAME, NAME_SRC_TIME)
     VALUES (#{row.stationCode}, #{row.stationName}, #{src})

UPDATE POS_PRESENCE_DAILY
   SET LAST_OUT_TIME = COALESCE(GREATEST(LAST_OUT_TIME, #{outTime}), #{outTime})
 WHERE CARD_CODE = #{cardCode}
   AND STAT_DATE BETWEEN #{fromDate} AND #{toDate}
